// =========================================================================
// [DodamRichgoAPI] 리치고(Richgo m.richgo.ai) MCP API 실시간 클라이언트
// https://m.richgo.ai/developers/mcp.html#tool-schools
// =========================================================================
window.DodamRichgoAPI = {
  endpoint: 'https://m.richgo.ai/api/mcp',
  cache: new Map(),

  async call(method, args) {
    const cacheKey = method + ':' + JSON.stringify(args);
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }
    try {
      const resp = await fetch(this.endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify({
          jsonrpc: '2.0',
          id: Date.now(),
          method: 'tools/call',
          params: {
            name: method,
            arguments: args
          }
        })
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const data = await resp.json();
      const content = data?.result?.structuredContent;
      if (content) {
        this.cache.set(cacheKey, content);
        return content;
      }
      return null;
    } catch (e) {
      console.warn(`[Richgo MCP] ${method} call failed:`, e);
      return null;
    }
  },

  async searchApartments(query) {
    if (!query || !query.trim()) return [];
    const q = query.trim();

    // 1. 온라인 실시간 API 호출
    try {
      const res = await this.call('search_apartments', { query: q });
      if (res && Array.isArray(res.results) && res.results.length > 0) {
        return res.results;
      }
    } catch (err) {}

    // 2. 오프라인/로컬 사전 수집 DB 매칭 폴백
    const db = window.DODAM_RICHGO_DATABASE?.apartments || {};
    const localMatches = [];
    const cleanQ = q.replace(/\s+/g, '').toLowerCase();
    for (const [key, apt] of Object.entries(db)) {
      const name = (apt.name || key).replace(/\s+/g, '').toLowerCase();
      const addr = (apt.address || '').replace(/\s+/g, '').toLowerCase();
      if (name.includes(cleanQ) || cleanQ.includes(name) || addr.includes(cleanQ)) {
        localMatches.push({
          danji_id: apt.danji_id,
          name: apt.name || key,
          address: apt.address || '',
          url: `https://m.richgo.ai/realty/danji/${apt.danji_id}`
        });
      }
    }
    return localMatches;
  },

  async getSchoolDistrict(danjiId) {
    if (!danjiId) return null;

    // 1. 온라인 실시간 API 호출
    try {
      const res = await this.call('get_school_district', { danji_id: danjiId, per_level: 4 });
      if (res && Array.isArray(res.schools) && res.schools.length > 0) {
        return res;
      }
    } catch (err) {}

    // 2. 오프라인/로컬 사전 수집 DB 매칭 폴백
    const db = window.DODAM_RICHGO_DATABASE?.apartments || {};
    for (const apt of Object.values(db)) {
      if (apt.danji_id === danjiId) {
        return {
          danji_id: apt.danji_id,
          name: apt.name,
          address: apt.address,
          schools: apt.schools || [],
          url: `https://m.richgo.ai/realty/danji/${apt.danji_id}`,
          source: '리치고(Richgo) m.richgo.ai'
        };
      }
    }
    return null;
  },

  async getSchoolDetail(level, schoolId) {
    if (!level || !schoolId) return null;

    // 1. 온라인 실시간 API 호출
    try {
      const res = await this.call('get_school', { level, school_id: schoolId });
      if (res && res.name) return res;
    } catch (err) {}

    // 2. 사전 캐싱된 상세 프로필 폴백
    const details = window.DODAM_RICHGO_DATABASE?.school_details || {};
    if (details[schoolId]) {
      return details[schoolId];
    }

    // 3. 기본 학군 DB 폴백
    const sdb = window.DODAM_RICHGO_DATABASE?.schools || {};
    if (sdb[schoolId]) {
      return sdb[schoolId];
    }
    return null;
  },

  findRichgoSchool(school) {
    if (!school) return null;
    const sdb = window.DODAM_RICHGO_DATABASE?.schools || {};
    const details = window.DODAM_RICHGO_DATABASE?.school_details || {};

    if (school.richgoSchoolId && (details[school.richgoSchoolId] || sdb[school.richgoSchoolId])) {
      return details[school.richgoSchoolId] || sdb[school.richgoSchoolId];
    }

    const cleanName = school.name.replace(/\s+/g, '');
    for (const [sid, s] of Object.entries(details)) {
      const sName = (s.name || '').replace(/\s+/g, '');
      if (cleanName === sName || cleanName.includes(sName) || sName.includes(cleanName)) {
        return s;
      }
    }
    for (const [sid, s] of Object.entries(sdb)) {
      const sName = (s.name || '').replace(/\s+/g, '');
      if (cleanName === sName || cleanName.includes(sName) || sName.includes(cleanName)) {
        return s;
      }
    }
    return null;
  }
};
